function openAudio(){if(state.screen==='race'&&['racing','countdown'].includes(state.session?.status))pauseRace();$('graphicsQuality').value=preferences.quality;$('enableGhost').checked=preferences.ghost;$('enableHaptics').checked=preferences.haptics;$('textSize').value=preferences.textSize;$('colorblindMode').checked=preferences.colorblind;$('tiltSteering').checked=preferences.tilt;$('audioMute').checked=sound.settings.mute;$('musicVolume').value=Math.round(sound.settings.music*100);$('engineVolume').value=Math.round(sound.settings.engine*100);$('effectsVolume').value=Math.round(sound.settings.effects*100);RacePatchAV.settings(sound);open('audioDialog')}
