$('importCsvFile').onchange=async e=>{if(!BlokRayaModes.requireTeacher()){e.target.value='';return;}const file=e.target.files[0];e.target.value='';if(!file)return;try{const b=bank();if(!b)throw Error('Pilih bank soal terlebih dahulu.');if(file.size>5*1024*1024)throw Error('CSV terlalu besar. Gunakan berkas di bawah 5 MB.');const qs=C.parseCSV(await file.text());if(!await ask('Tambahkan '+qs.length+' soal?','Soal CSV akan ditambahkan ke bank “'+b.title+'”. Soal yang sudah ada tetap disimpan.','Impor soal'))return;if(!BlokRayaModes.requireTeacher())return;b.questions.push(...qs);b.settings.count=C.clamp(b.settings.count,1,b.questions.length);saved(qs.length+' soal ditambahkan.');state.questionPage=Math.floor((b.questions.length-1)/5);renderTeacher()}catch(err){toast('Impor belum berhasil: '+err.message)}};
