document.querySelectorAll('[data-control]').forEach(b=>{const key=b.dataset.control;const release=e=>{controls[key]=false;b.classList.remove('down');if(e?.pointerId!==undefined&&b.hasPointerCapture(e.pointerId))b.releasePointerCapture(e.pointerId)};b.onpointerdown=e=>{e.preventDefault();if(state.screen!=='race'||!['racing','countdown'].includes(state.session?.status))return;controls[key]=true;b.classList.add('down');b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=release});
const keymap={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'gas',w:'gas',W:'gas',ArrowDown:'brake',s:'brake',S:'brake'};
document.addEventListener('keydown',e=>{
 if(state.screen!=='race')return;const s=state.session;if(!s)return;
 if(document.querySelector('dialog[open]')){if(e.key==='Escape'&&$('pauseDialog').open){e.preventDefault();resumeRace()}return}
 if(keymap[e.key]){e.preventDefault();controls[keymap[e.key]]=true}if(e.key==='Shift'){e.preventDefault();controls.jump=true}if(e.key==='c'||e.key==='C'){e.preventDefault();controls.drift=true}if((e.key==='r'||e.key==='R')&&!e.repeat){s.reset();raceNotice('Kart kembali ke tengah lintasan.');haptic(40)}
 if(!e.repeat&&['q','Q','1','2'].includes(e.key)){e.preventDefault();s.selectSlot(e.key==='1'?0:e.key==='2'?1:1-s.selectedSlot);updateHud()}
 if((e.key==='e'||e.key==='E'||e.code==='Space')&&!e.repeat){e.preventDefault();useItem()}
 if(e.key==='Escape'||e.key==='p'||e.key==='P'){e.preventDefault();pauseRace()}
});
